// Normalize the incoming lead payload so downstream nodes
// always see the same shape, wherever the form data comes from.
const b = $json.body ?? $json;
return [{ json: {
  name: b.name ?? '',
  email: b.email ?? '',
  company: b.company ?? '',
  company_size: b.company_size ?? null,
  role: b.role ?? '',
  budget_range: b.budget_range ?? null,
  source: b.source ?? 'website',
  website: b.website ?? null,
  message: b.message ?? ''
}}];

// SIMULATED OUTREACH — this message is LOGGED, never sent.
// There is no email/SMS API anywhere in this workflow.
const contact = $('Create CRM Contact').first().json;
const lead = contact.lead;
const message =
  `Hi ${lead.name},\n\n` +
  `Thanks for your interest! Based on what you shared about ${lead.company}, ` +
  `I believe we can help with your inquiry.\n\n` +
  `Would a short 15-minute call this week work to explore it?\n\n` +
  `Best regards,\n(Your Name) — demo outreach, simulated only`;
return [{ json: {
  contact_id: contact.contact_id,
  lead: lead,
  message: message,
  simulated: true,
  sent: false
}}];
